// Wissensbasis für den KI-Coach (eigene Formulierungen, Stand September 2026). Jeder Eintrag ist quellenbelegt
// mit allgemein dokumentierten Regeln; Zweifelsfälle stehen auf reviewStatus "needs_verification".
import { defaultLicenseCodes, materialKindOf } from "./topics";
import { CONTENT_SOURCE, LEGAL_BASIS_DATE, type KnowledgeEntry, type ReviewStatus, type TopicCode } from "./types";

function k(topic: TopicCode, slug: string, title: string, summary: string, legalReference: string, bodyMarkdown: string, reviewStatus: ReviewStatus = "published"): KnowledgeEntry {
  return {
    slug,
    title,
    topic,
    summary,
    bodyMarkdown: bodyMarkdown.trim() + "\n",
    legalReference,
    legalBasisDate: LEGAL_BASIS_DATE,
    licenseCodes: defaultLicenseCodes(materialKindOf(topic)),
    source: CONTENT_SOURCE,
    reviewStatus,
  };
}

export const knowledgeEntries: readonly KnowledgeEntry[] = [
  // Gefahrenlehre
  k("gefahrenlehre", "reaktionszeit", "Reaktionszeit", "Ein aufmerksamer Fahrer braucht etwa eine Sekunde, um auf eine Gefahr zu reagieren.", "Faustformel Fahrausbildung",
    "Die Reaktionszeit ist die Zeit zwischen dem Erkennen einer Gefahr und dem Beginn der Bremsung. Die Faustformel rechnet mit etwa einer Sekunde. In dieser Sekunde legt ein Fahrzeug bei 50 km/h rund 15 Meter zurück. Müdigkeit, Alkohol, Drogen, Medikamente und Ablenkung verlängern die Reaktionszeit deutlich. Der in der Reaktionszeit zurückgelegte Weg heißt Reaktionsweg."),
  k("gefahrenlehre", "anhalteweg", "Anhalteweg", "Der Anhalteweg ist die Summe aus Reaktionsweg und Bremsweg.", "Faustformel Fahrausbildung",
    "Der Anhalteweg setzt sich aus dem Reaktionsweg und dem Bremsweg zusammen. Der Reaktionsweg wird mit (km/h ÷ 10) × 3 geschätzt, der Bremsweg mit (km/h ÷ 10)². Bei 50 km/h ergibt das 15 Meter plus 25 Meter, also 40 Meter. Bei 100 km/h sind es 30 Meter plus 100 Meter, also 130 Meter. Bei einer Gefahrenbremsung halbiert sich der Bremsweg ungefähr, der Reaktionsweg bleibt gleich."),
  k("gefahrenlehre", "handy-am-steuer", "Elektronische Geräte am Steuer", "Ein Gerät darf beim Fahren nur benutzt werden, wenn es weder aufgenommen noch gehalten wird.", "§ 23 Abs. 1a und 1b StVO",
    "Wer ein Fahrzeug führt, darf ein elektronisches Gerät nur benutzen, wenn es dafür weder aufgenommen noch gehalten wird. Bei Bedienung per Sprachsteuerung oder mit kurzem Blick, der an die Verkehrslage angepasst ist, bleibt die Nutzung erlaubt. Die Regel gilt auch im Stand bei laufendem Motor, etwa an einer roten Ampel. Nur bei stehendem Fahrzeug mit vollständig ausgeschaltetem Motor darf das Gerät in die Hand genommen werden. Ein von der Start-Stopp-Automatik nur vorübergehend abgeschalteter Motor gilt dabei nicht als ausgeschaltet."),
  k("gefahrenlehre", "toter-winkel-schulterblick", "Toter Winkel und Schulterblick", "Spiegel decken nicht alles ab; vor jedem Richtungswechsel gehört der Schulterblick dazu.", "§ 9 Abs. 1 StVO; § 7 Abs. 5 StVO",
    "Der tote Winkel ist der Bereich schräg neben und hinter dem Fahrzeug, den Innen- und Außenspiegel nicht zeigen. Radfahrende, Motorräder und Fußgänger verschwinden dort leicht. Deshalb gehört zu jedem Abbiegen und jedem Fahrstreifenwechsel ein Schulterblick über die Schulter in die Richtung, in die gefahren werden soll. Die richtige Reihenfolge lautet: Spiegel, Blinker, Schulterblick, dann handeln."),
  // Recht
  k("recht", "probezeit", "Probezeit", "Die Probezeit dauert zwei Jahre und verlängert sich bei schwerwiegenden Verstößen um zwei Jahre.", "§ 2a StVG",
    "Nach dem erstmaligen Erwerb der Fahrerlaubnis gilt eine Probezeit von zwei Jahren. Bei einem schwerwiegenden Verstoß (A-Verstoß) oder zwei weniger schwerwiegenden Verstößen (B-Verstöße) wird ein Aufbauseminar angeordnet und die Probezeit um zwei Jahre verlängert. In der Probezeit gilt außerdem ein absolutes Alkoholverbot am Steuer. Wird die Fahrerlaubnis entzogen, beginnt nach der Neuerteilung eine neue Probezeit für die Restdauer."),
  k("recht", "theoriepruefung-klasse-b", "Theoretische Prüfung Klasse B", "Beim Ersterwerb 30 Fragen, bestanden mit höchstens zehn Fehlerpunkten, aber nicht zwei Fünf-Punkte-Fragen falsch.", "Anlage 7 FeV",
    "Die theoretische Prüfung für den Ersterwerb der Klasse B umfasst 30 Fragen aus Grundstoff und Zusatzstoff. Bestanden ist sie mit höchstens zehn Fehlerpunkten, sofern nicht zwei Fragen mit je fünf Punkten falsch beantwortet wurden. Die bestandene Theorieprüfung ist zwölf Monate gültig; innerhalb dieser Frist muss die praktische Prüfung bestanden werden. Nach einer nicht bestandenen Prüfung gilt eine Sperrfrist von zwei Wochen bis zum nächsten Versuch."),
  k("recht", "sonderfahrten", "Sonderfahrten", "Für Klasse B sind mindestens fünf Überland-, vier Autobahn- und drei Nachtfahrten vorgeschrieben.", "§ 5 FahrschAusbO",
    "Die Fahrschüler-Ausbildungsordnung schreibt für die Klasse B besondere Ausbildungsfahrten vor: mindestens fünf Überlandfahrten, vier Autobahnfahrten und drei Fahrten bei Dunkelheit. Jede Sonderfahrt dauert 45 Minuten. Die Anzahl der übrigen Fahrstunden ist nicht vorgeschrieben und hängt vom Lernfortschritt ab. Die Sonderfahrten werden erst absolviert, wenn die Grundausbildung ausreichend fortgeschritten ist."),
  k("recht", "bf17-begleitperson", "Begleitetes Fahren ab 17", "Begleitpersonen müssen mindestens 30 Jahre alt sein, fünf Jahre Klasse B besitzen und dürfen höchstens einen Punkt haben.", "§ 48a FeV",
    "Beim Begleiteten Fahren ab 17 darf der Fahranfänger nur in Begleitung eingetragener Personen fahren. Eine Begleitperson muss mindestens 30 Jahre alt sein, seit mindestens fünf Jahren die Fahrerlaubnis Klasse B besitzen und darf zum Zeitpunkt der Eintragung höchstens einen Punkt im Fahreignungsregister haben. Für die Begleitperson gilt eine Grenze von 0,5 Promille; sie darf nicht unter Drogeneinfluss stehen. Mit dem 18. Geburtstag entfällt die Begleitpflicht."),
  k("recht", "b197-automatik", "Schlüsselzahl B197", "Prüfung auf Automatik ohne Automatikbeschränkung nach zehn Schaltstunden und einer 15-minütigen Testfahrt.", "Anlage 7 FeV; § 17 FeV",
    "Mit der Schlüsselzahl B197 wird die praktische Prüfung auf einem Automatikfahrzeug abgelegt, ohne dass der Führerschein auf Automatik beschränkt wird. Voraussetzung sind mindestens zehn Fahrstunden zu 45 Minuten auf einem Fahrzeug mit Schaltgetriebe und eine von der Fahrschule bescheinigte Testfahrt von mindestens 15 Minuten auf einem Schaltwagen. Der Prüfer stellt keine Schaltkompetenz fest; der Nachweis erfolgt allein durch die Fahrschule."),
  k("recht", "b196-leichtkraftrad", "Schlüsselzahl B196", "Nach einer Schulung ohne Prüfung dürfen Inhaber der Klasse B in Deutschland Leichtkrafträder fahren.", "§ 6 Abs. 4 FeV; Anlage 7b FeV",
    "Die Schlüsselzahl B196 erlaubt Inhabern der Klasse B das Führen von Krafträdern der Klasse A1 (bis 125 cm³ und 11 kW). Voraussetzung sind ein Mindestalter von 25 Jahren, mindestens fünf Jahre Besitz der Klasse B und eine Fahrschulschulung aus Theorie und Praxis. Eine Prüfung findet nicht statt. B196 gilt nur in Deutschland und kann nicht zur Klasse A2 aufgestockt werden."),
  k("recht", "fahreignungsregister-punkte", "Punkte im Fahreignungsregister", "Bei acht Punkten wird die Fahrerlaubnis entzogen; vorher gibt es Ermahnung und Verwarnung.", "§ 4 StVG",
    "Verkehrsverstöße werden je nach Schwere mit einem, zwei oder drei Punkten im Fahreignungsregister eingetragen. Bei vier bis fünf Punkten erfolgt eine Ermahnung, bei sechs bis sieben Punkten eine Verwarnung. Bei acht Punkten wird die Fahrerlaubnis entzogen. Punkte verfallen nach festen Fristen, die je nach Schwere des Verstoßes zwischen zweieinhalb und zehn Jahren liegen."),
  k("recht", "klasse-b-umfang", "Umfang der Klasse B", "Kraftfahrzeuge bis 3.500 kg mit höchstens acht Sitzplätzen außer dem Fahrersitz, Anhänger bis 750 kg immer.", "§ 6 FeV",
    "Die Klasse B berechtigt zum Führen von Kraftfahrzeugen mit einer zulässigen Gesamtmasse bis 3.500 kg und höchstens acht Sitzplätzen außer dem Fahrersitz. Ein Anhänger bis 750 kg zulässiger Gesamtmasse darf immer mitgeführt werden. Ein schwererer Anhänger ist erlaubt, wenn die zulässige Gesamtmasse der Kombination 3.500 kg nicht übersteigt. Für Kombinationen bis 4.250 kg ist B96 nötig, darüber die Klasse BE."),
  // Verkehrszeichen
  k("verkehrszeichen", "zeichenarten", "Arten von Verkehrszeichen", "Gefahrzeichen sind dreieckig, Vorschriftzeichen meist rund, Richtzeichen meist rechteckig.", "§§ 40 bis 42 StVO",
    "Gefahrzeichen sind dreieckig mit rotem Rand und mahnen zu erhöhter Aufmerksamkeit; außerorts stehen sie in der Regel 150 bis 250 Meter vor der Gefahrstelle. Vorschriftzeichen sind meist rund und enthalten Gebote oder Verbote. Richtzeichen sind meist rechteckig oder quadratisch und geben Hinweise wie Vorfahrtstraße oder Parkplatz. Zusatzzeichen unter einem Verkehrszeichen ändern oder beschränken dessen Bedeutung."),
  k("verkehrszeichen", "stoppschild", "Stoppschild (Zeichen 206)", "Am Stoppschild muss immer angehalten werden, auch ohne sichtbaren Verkehr.", "§ 41 StVO, Anlage 2 (Zeichen 206)",
    "Das Zeichen 206 verlangt immer ein vollständiges Anhalten. Angehalten wird an der Haltlinie oder, wenn keine vorhanden ist, an der Sichtlinie, von der aus die Kreuzung übersehen werden kann. Danach ist Vorfahrt zu gewähren. Auch bei freier Kreuzung und guter Sicht darf nicht ohne Stillstand weitergefahren werden."),
  k("verkehrszeichen", "vorfahrt-gewaehren", "Vorfahrt gewähren (Zeichen 205)", "Das auf der Spitze stehende Dreieck verpflichtet zum Warten, wenn bevorrechtigter Verkehr kommt.", "§ 41 StVO, Anlage 2 (Zeichen 205)",
    "Das Zeichen 205 zeigt an, dass die kreuzende Straße Vorfahrt hat. Angehalten werden muss nur, wenn es die Verkehrslage erfordert. Ist die Kreuzung frei, darf ohne Anhalten weitergefahren werden. Das Zeichen steht auch an den Zufahrten der meisten Kreisverkehre und gibt dem Verkehr im Kreis die Vorfahrt."),
  k("verkehrszeichen", "verkehrsberuhigter-bereich", "Verkehrsberuhigter Bereich (Zeichen 325.1)", "Schrittgeschwindigkeit, Fußgänger auf der ganzen Straße, Parken nur auf gekennzeichneten Flächen.", "§ 42 StVO, Anlage 3 (Zeichen 325.1)",
    "Im verkehrsberuhigten Bereich dürfen Fahrzeuge nur mit Schrittgeschwindigkeit fahren. Fußgänger dürfen die Straße in ganzer Breite benutzen und Kinder überall spielen; sie dürfen weder gefährdet noch behindert werden. Parken ist nur auf gekennzeichneten Flächen erlaubt, Halten zum Ein- und Aussteigen oder Be- und Entladen ist möglich. Wer aus dem Bereich auf eine andere Straße fährt, muss alle anderen durchfahren lassen."),
  k("verkehrszeichen", "halteverbote", "Eingeschränktes und absolutes Halteverbot", "Zeichen 286 erlaubt drei Minuten Halten, Zeichen 283 verbietet jedes Halten.", "§ 41 StVO, Anlage 2 (Zeichen 283 und 286)",
    "Im eingeschränkten Halteverbot (Zeichen 286, ein Schrägstrich) ist das Halten bis zu drei Minuten erlaubt, länger nur zum Ein- und Aussteigen oder zum Be- und Entladen. Im absoluten Halteverbot (Zeichen 283, zwei Schrägstriche) ist jedes Halten verboten, verkehrsbedingtes Warten ausgenommen. Pfeile auf dem Zeichen zeigen Anfang, Ende oder Fortsetzung des Verbots an."),
  k("verkehrszeichen", "fahrradstrasse", "Fahrradstraße (Zeichen 244.1)", "Tempo 30, Radfahrende dürfen nebeneinander fahren, Kraftfahrzeuge nur mit Zusatzzeichen.", "§ 41 StVO, Anlage 2 (Zeichen 244.1)",
    "In einer Fahrradstraße gilt eine Höchstgeschwindigkeit von 30 km/h. Radfahrende dürfen nebeneinander fahren. Anderer Fahrzeugverkehr ist nur zugelassen, wenn ein Zusatzzeichen dies erlaubt, etwa für Anlieger. Wer dort fahren darf, muss die Geschwindigkeit bei Bedarf weiter verringern und darf den Radverkehr weder gefährden noch behindern."),
  // Straßenbenutzung
  k("strassenbenutzung", "rettungsgasse", "Rettungsgasse", "Sobald der Verkehr stockt: links nach links, alle anderen nach rechts.", "§ 11 Abs. 2 StVO",
    "Auf Autobahnen und Außerortsstraßen mit mindestens zwei Fahrstreifen je Richtung muss bei stockendem Verkehr eine Rettungsgasse gebildet werden. Fahrzeuge auf dem linken Fahrstreifen weichen nach links aus, alle anderen nach rechts. Die Gasse liegt also immer zwischen dem ganz linken und dem unmittelbar rechts daneben liegenden Fahrstreifen. Sie ist zu bilden, sobald Fahrzeuge mit Schrittgeschwindigkeit fahren oder stehen, nicht erst bei Blaulicht. Der Seitenstreifen bleibt frei."),
  k("strassenbenutzung", "autobahn-regeln", "Regeln auf der Autobahn", "Nur Kraftfahrzeuge über 60 km/h; Wenden, Rückwärtsfahren und Halten sind verboten.", "§ 18 StVO",
    "Autobahnen und Kraftfahrstraßen dürfen nur mit Kraftfahrzeugen benutzt werden, deren bauartbedingte Höchstgeschwindigkeit mehr als 60 km/h beträgt. Wer auffährt, hat keine Vorfahrt und nutzt den Beschleunigungsstreifen zum Anpassen der Geschwindigkeit. Wenden, Rückwärtsfahren und Halten sind verboten; der Seitenstreifen darf nur in Notfällen oder bei Freigabe durch Verkehrszeichen befahren werden. Wer eine Ausfahrt verpasst, fährt zur nächsten weiter."),
  k("strassenbenutzung", "richtgeschwindigkeit", "Richtgeschwindigkeit 130 km/h", "Eine Empfehlung, kein Limit; wer schneller fährt, kann bei einem Unfall mithaften.", "Autobahn-Richtgeschwindigkeits-Verordnung",
    "Auf Autobahnen gilt für Pkw ohne Beschilderung keine allgemeine Höchstgeschwindigkeit, aber eine Richtgeschwindigkeit von 130 km/h. Sie ist eine Empfehlung. Wer deutlich schneller fährt und in einen Unfall verwickelt wird, muss auch ohne eigenes Verschulden mit einer Mithaftung wegen erhöhter Betriebsgefahr rechnen."),
  k("strassenbenutzung", "reissverschlussverfahren", "Reißverschlussverfahren", "Bei Fahrstreifenverengung erst unmittelbar vor der Engstelle abwechselnd einordnen.", "§ 7 Abs. 4 StVO",
    "Endet ein Fahrstreifen oder ist er nicht durchgehend befahrbar, dürfen beide Fahrstreifen bis zur Verengung genutzt werden. Unmittelbar vor der Engstelle fädeln die Fahrzeuge abwechselnd ein. Die Fahrzeuge auf dem durchgehenden Fahrstreifen müssen das Einordnen ermöglichen. Frühes Einordnen verschenkt Fahrbahnfläche und verlängert den Stau."),
  k("strassenbenutzung", "kinder-radfahren-gehweg", "Kinder auf dem Rad", "Bis acht Jahre Gehwegpflicht, bis zehn Jahre Gehweg erlaubt, Begleitung ab 16 Jahren möglich.", "§ 2 Abs. 5 StVO",
    "Kinder bis zum vollendeten achten Lebensjahr müssen mit dem Fahrrad den Gehweg benutzen; alternativ dürfen sie baulich getrennte Radwege nutzen. Kinder bis zum vollendeten zehnten Lebensjahr dürfen den Gehweg benutzen. Eine geeignete Aufsichtsperson ab 16 Jahren darf ein Kind bis acht Jahre auf dem Gehweg mit dem Rad begleiten. Auf Fußgänger ist besondere Rücksicht zu nehmen."),
  // Vorfahrt
  k("vorfahrt", "rechts-vor-links", "Rechts vor links", "Ohne Zeichen hat an Kreuzungen und Einmündungen Vorfahrt, wer von rechts kommt.", "§ 8 Abs. 1 StVO",
    "An Kreuzungen und Einmündungen ohne Verkehrszeichen und ohne Lichtzeichen gilt die Grundregel rechts vor links. Sie gilt auch an T-Einmündungen: Die durchgehende Straße hat keinen automatischen Vorrang. Die Regel gilt nicht für Fahrzeuge, die aus Feld- oder Waldwegen kommen. Kommen an einer Kreuzung Fahrzeuge aus allen Richtungen, hilft nur Verständigung."),
  k("vorfahrt", "einfahren-grundstueck", "Einfahren aus Grundstücken", "Wer aus einem Grundstück oder über einen abgesenkten Bordstein einfährt, muss alle anderen durchfahren lassen.", "§ 10 StVO",
    "Wer aus einem Grundstück, einer Fußgängerzone, einem verkehrsberuhigten Bereich oder über einen abgesenkten Bordstein auf die Straße einfährt, hat keine Vorfahrt. Er muss sich so verhalten, dass eine Gefährdung anderer ausgeschlossen ist, und alle anderen durchfahren lassen, auch Fußgänger und Radfahrende auf Gehweg und Radweg. Rechts vor links gilt hier nicht."),
  k("vorfahrt", "linksabbiegen-gegenverkehr", "Linksabbiegen und Gegenverkehr", "Wer links abbiegt, muss entgegenkommende Fahrzeuge durchfahren lassen.", "§ 9 Abs. 3 StVO",
    "Wer links abbiegen will, muss entgegenkommende Fahrzeuge durchfahren lassen, die geradeaus fahren oder rechts abbiegen. Das gilt unabhängig davon, wer zuerst an der Kreuzung war. Ebenso sind Radfahrende und Fußgänger, die die Straße kreuzen, in die abgebogen wird, durchzulassen. Entgegenkommende Linksabbieger biegen voreinander ab, wenn Markierungen nichts anderes vorgeben."),
  k("vorfahrt", "einsatzfahrzeuge", "Einsatzfahrzeuge mit Blaulicht und Einsatzhorn", "Blaues Blinklicht mit Einsatzhorn bedeutet: sofort freie Bahn schaffen.", "§ 38 Abs. 1 StVO",
    "Blaues Blinklicht zusammen mit dem Einsatzhorn bedeutet, dass alle übrigen Verkehrsteilnehmer sofort freie Bahn zu schaffen haben. Das gilt auch auf Vorfahrtstraßen und bei Grün an einer Ampel. Man fährt nach rechts, hält wenn nötig an und weicht nicht auf die Gegenfahrbahn aus. Blaues Blinklicht allein, ohne Einsatzhorn, warnt lediglich vor einer Unfall- oder Einsatzstelle."),
  k("vorfahrt", "abknickende-vorfahrt", "Abknickende Vorfahrtstraße", "Wer dem Verlauf folgt, behält die Vorfahrt, muss aber blinken.", "§ 9 Abs. 1 StVO; Zeichen 306 mit Zusatzzeichen",
    "Ein Zusatzzeichen unter dem Zeichen Vorfahrtstraße zeigt den abknickenden Verlauf. Wer dem Verlauf folgt, behält die Vorfahrt, ändert aber die Fahrtrichtung und muss deshalb rechtzeitig und deutlich blinken. Wer die Vorfahrtstraße geradeaus verlässt, muss warten und ebenfalls die Abbiegeregeln beachten. Zwischen den nicht bevorrechtigten Straßen gilt rechts vor links."),
  // Verkehrsregelung
  k("verkehrsregelung", "ampelphasen", "Bedeutung der Ampelphasen", "Rot heißt Halt, Rot-Gelb heißt fahrbereit machen, Gelb heißt vor der Kreuzung warten.", "§ 37 Abs. 2 StVO",
    "Rot bedeutet Halt vor der Kreuzung beziehungsweise an der Haltlinie. Rot und Gelb zusammen kündigen Grün an; gefahren wird erst bei Grün. Gelb bedeutet, vor der Kreuzung auf das nächste Zeichen zu warten. Nur wer so nah an der Kreuzung ist, dass ein gefahrloses Anhalten nicht mehr möglich ist, darf bei Gelb noch weiterfahren. Grün gibt den Verkehr frei, verpflichtet aber weiterhin zur Rücksicht auf Fußgänger, die die Fahrbahn noch räumen."),
  k("verkehrsregelung", "gruenpfeilschild", "Grünpfeilschild (Zeichen 720)", "Rechtsabbiegen bei Rot nach vollständigem Anhalten, wenn niemand behindert oder gefährdet wird.", "§ 37 Abs. 2 Nr. 1 StVO",
    "Ein Schild mit grünem Pfeil auf schwarzem Grund neben dem roten Licht erlaubt das Rechtsabbiegen bei Rot. Vorher muss an der Haltlinie vollständig angehalten werden. Abgebogen werden darf nur, wenn weder Fußgänger noch der freigegebene Verkehr behindert oder gefährdet werden. Für den Radverkehr gibt es ein eigenes Grünpfeilschild (Zeichen 721). Ein grün leuchtender Pfeil in der Ampel ist etwas anderes: Er gibt die Richtung ohne Anhaltepflicht frei."),
  k("verkehrsregelung", "polizei-handzeichen", "Zeichen von Polizeibeamten", "Arme quer zur Fahrtrichtung (Brust oder Rücken zugewandt) bedeuten Halt, wer in Armrichtung fährt hat freie Fahrt, erhobener Arm kündigt Wechsel an.", "§ 36 Abs. 2 StVO",
    "Zeichen und Weisungen von Polizeibeamten gehen allen anderen Regelungen vor. Sind die Arme seitlich ausgestreckt und Ihnen ist Brust oder Rücken zugewandt, stehen die Arme quer zu Ihrer Fahrtrichtung; das bedeutet Halt vor der Kreuzung wie Rot. Wer in Richtung der Arme fährt, also den Beamten von der Seite sieht, hat freie Fahrt wie Grün. Ein hoch erhobener Arm bedeutet Achtung, die Freigabe wechselt; wer noch nicht in der Kreuzung ist, hält an."),
  k("verkehrsregelung", "dauerlichtzeichen", "Dauerlichtzeichen über Fahrstreifen", "Rotes Kreuz sperrt, grüner Pfeil gibt frei, gelber Schrägpfeil kündigt Wechsel an.", "§ 37 Abs. 3 StVO",
    "Dauerlichtzeichen über einzelnen Fahrstreifen regeln deren Benutzung. Ein rotes Kreuz bedeutet, dass der Fahrstreifen nicht benutzt werden darf. Ein grüner, nach unten zeigender Pfeil gibt ihn frei. Ein gelb blinkender Schrägpfeil kündigt an, dass der Fahrstreifen in Pfeilrichtung zu verlassen ist."),
  // Geschwindigkeit
  k("geschwindigkeit", "hoechstgeschwindigkeiten-pkw", "Höchstgeschwindigkeiten für Pkw", "Innerorts 50 km/h, außerorts 100 km/h, mit Anhänger 80 km/h, Autobahn Richtgeschwindigkeit 130.", "§ 3 Abs. 3 StVO",
    "Innerhalb geschlossener Ortschaften gilt für alle Kraftfahrzeuge 50 km/h, wenn keine Zeichen etwas anderes anordnen. Außerhalb geschlossener Ortschaften dürfen Pkw ohne Anhänger 100 km/h fahren. Pkw mit Anhänger dürfen außerorts und auf Autobahnen 80 km/h, mit Tempo-100-Zulassung des Gespanns 100 km/h. Auf Autobahnen gilt für Pkw ohne Beschilderung die Richtgeschwindigkeit von 130 km/h. Mit Schneeketten sind höchstens 50 km/h erlaubt."),
  k("geschwindigkeit", "sichtweite-unter-50-metern", "Sichtweite unter 50 Metern", "Bei Nebel, Schneefall oder Regen mit Sicht unter 50 Metern gilt höchstens 50 km/h.", "§ 3 Abs. 1 StVO",
    "Grundsätzlich darf nur so schnell gefahren werden, dass innerhalb der übersehbaren Strecke angehalten werden kann. Beträgt die Sichtweite durch Nebel, Schneefall oder Regen weniger als 50 Meter, darf nicht schneller als 50 km/h gefahren werden, wenn nicht eine geringere Geschwindigkeit geboten ist. Bei dieser Sichtweite darf zugleich die Nebelschlussleuchte eingeschaltet werden."),
  k("geschwindigkeit", "sicherheitsabstand", "Sicherheitsabstand", "Halber Tacho in Metern, außerorts die Zwei-Sekunden-Regel, Lkw auf der Autobahn 50 Meter.", "§ 4 StVO",
    "Der Abstand zum Vorausfahrenden muss so groß sein, dass auch bei plötzlichem Bremsen angehalten werden kann. Als Faustregel gilt halber Tacho: bei 100 km/h mindestens 50 Meter, was etwa dem Abstand zweier Leitpfosten auf der Autobahn entspricht. Außerorts hilft die Zwei-Sekunden-Regel, bei Nässe und Glätte ist der Abstand deutlich zu vergrößern. Lkw über 3,5 t und Kraftomnibusse müssen auf Autobahnen bei mehr als 50 km/h mindestens 50 Meter Abstand halten."),
  k("geschwindigkeit", "bremsweg-faustformel", "Faustformel für den Bremsweg", "Bremsweg = (km/h ÷ 10)², bei Gefahrenbremsung etwa die Hälfte.", "Faustformel Fahrausbildung",
    "Der Bremsweg bei normaler Bremsung wird mit (km/h ÷ 10)² geschätzt. Bei 50 km/h sind das 25 Meter, bei 100 km/h 100 Meter. Der Bremsweg wächst mit dem Quadrat der Geschwindigkeit: doppeltes Tempo bedeutet vierfachen Bremsweg. Bei einer Gefahrenbremsung halbiert sich der Wert ungefähr. Nässe, Glätte, abgefahrene Reifen und verschlissene Stoßdämpfer verlängern den Bremsweg."),
  // Andere Teilnehmer
  k("andere_teilnehmer", "ueberholabstand-radfahrer", "Überholabstand zu Radfahrenden", "Innerorts mindestens 1,5 Meter, außerorts mindestens 2 Meter Seitenabstand.", "§ 5 Abs. 4 StVO",
    "Beim Überholen von zu Fuß Gehenden, Radfahrenden und Elektrokleinstfahrzeugen muss ein seitlicher Mindestabstand von 1,5 Metern innerorts und 2 Metern außerorts eingehalten werden. Reicht die Fahrbahnbreite dafür nicht aus, darf nicht überholt werden. Der Abstand gilt auch, wenn Radfahrende auf einem Schutzstreifen fahren."),
  k("andere_teilnehmer", "fussgaengerueberweg", "Fußgängerüberweg (Zebrastreifen)", "Fußgänger, die erkennbar überqueren wollen, haben Vorrang; Überholen ist verboten.", "§ 26 StVO",
    "An Fußgängerüberwegen haben zu Fuß Gehende und Rollstuhlfahrende, die den Überweg erkennbar benutzen wollen, Vorrang. Fahrzeuge dürfen sich nur mit mäßiger Geschwindigkeit nähern und müssen nötigenfalls warten. Überholen ist am Fußgängerüberweg verboten. Stockt der Verkehr, darf nicht auf dem Überweg gehalten werden."),
  k("andere_teilnehmer", "linienbus-haltestelle", "Linienbusse an Haltestellen", "Bus mit Warnblinklicht: Schrittgeschwindigkeit für beide Richtungen; innerorts Abfahren ermöglichen.", "§ 20 StVO",
    "An Haltestellen darf an haltenden Linienbussen und Schulbussen nur vorsichtig vorbeigefahren werden. Hat der Bus das Warnblinklicht eingeschaltet, darf er beim Anfahren an die Haltestelle nicht überholt werden, und an der Haltestelle darf nur mit Schrittgeschwindigkeit und ausreichendem Abstand vorbeigefahren werden; das gilt auch für den Gegenverkehr. Innerorts ist Linienbussen das Abfahren von gekennzeichneten Haltestellen zu ermöglichen."),
  k("andere_teilnehmer", "e-scooter-regeln", "E-Scooter (Elektrokleinstfahrzeuge)", "Ab 14 Jahren, 20 km/h, Radwege oder Fahrbahn, keine Helmpflicht, keine Mitfahrer.", "Elektrokleinstfahrzeuge-Verordnung (eKFV)",
    "Elektrokleinstfahrzeuge wie E-Scooter dürfen ab 14 Jahren gefahren werden und haben eine bauartbedingte Höchstgeschwindigkeit von 20 km/h. Sie müssen Radwege und Radfahrstreifen benutzen, wenn vorhanden, sonst die Fahrbahn; Gehwege sind tabu. Eine Helmpflicht besteht nicht, die Mitnahme von Personen ist verboten. Für Alkohol gelten die gleichen Grenzen wie für Kraftfahrzeuge."),
  k("andere_teilnehmer", "lkw-rechtsabbiegen-schritt", "Lkw beim Rechtsabbiegen innerorts", "Fahrzeuge über 3,5 t dürfen innerorts nur mit Schrittgeschwindigkeit rechts abbiegen, wenn Rad- oder Fußverkehr zu erwarten ist.", "§ 9 Abs. 6 StVO",
    "Kraftfahrzeuge mit einer zulässigen Gesamtmasse über 3,5 t müssen innerorts beim Rechtsabbiegen Schrittgeschwindigkeit fahren, wenn mit Rad- oder Fußverkehr zu rechnen ist. Grund ist der große tote Winkel neben der Beifahrerseite. Radfahrende und Pkw-Fahrer sollten sich nie rechts neben einen Lkw stellen, der abbiegen könnte."),
  // Fahrmanöver
  k("fahrmanoever", "ueberholen-voraussetzungen", "Voraussetzungen für das Überholen", "Übersicht, kein Gegenverkehr, wesentlich höhere Geschwindigkeit, keine Gefährdung.", "§ 5 StVO",
    "Überholt wird grundsätzlich links. Es darf nur überholt werden, wenn die Strecke übersehbar ist, Gegenverkehr während des gesamten Vorgangs ausgeschlossen ist und der Überholende wesentlich schneller fahren kann als der Überholte. Niemand darf gefährdet werden. Überholverbote gelten bei unklarer Verkehrslage, an unübersichtlichen Stellen, an Fußgängerüberwegen, ab den Baken vor Bahnübergängen und bei Zeichen 276 oder durchgezogener Linie. Beim Überholen von Radfahrenden gelten die Mindestabstände von 1,5 und 2 Metern."),
  k("fahrmanoever", "abbiegen-reihenfolge", "Abbiegen richtig vorbereiten", "Spiegel, Blinker, Einordnen, Geschwindigkeit verringern, Schulterblick.", "§ 9 Abs. 1 StVO",
    "Wer abbiegen will, muss das rechtzeitig und deutlich mit dem Fahrtrichtungsanzeiger ankündigen und den nachfolgenden Verkehr beobachten. Rechtsabbieger ordnen sich möglichst weit rechts ein, Linksabbieger bis zur Fahrbahnmitte, in Einbahnstraßen ganz links. Vor dem Abbiegen wird die Geschwindigkeit verringert und der Schulterblick gemacht. Radfahrende und Fußgänger, die geradeaus wollen, sind durchzulassen."),
  k("fahrmanoever", "wenden-rueckwaertsfahren", "Wenden und Rückwärtsfahren", "Auf Autobahnen, Kraftfahrstraßen und in Einbahnstraßen ist Wenden verboten; rückwärts nur langsam und ohne Gefährdung.", "§ 9 Abs. 5 StVO; § 18 Abs. 7 StVO",
    "Beim Wenden und Rückwärtsfahren muss eine Gefährdung anderer ausgeschlossen sein; nötigenfalls ist ein Einweiser zu nutzen. Wer rückwärtsfährt, hat keinen Vorrang. Auf Autobahnen und Kraftfahrstraßen sind Wenden und Rückwärtsfahren verboten, in Einbahnstraßen ist Wenden unzulässig, weil man anschließend gegen die Fahrtrichtung fahren würde."),
  k("fahrmanoever", "rechts-schneller-innerorts", "Rechts schneller fahren innerorts", "Innerorts dürfen Kfz bis 3,5 t bei mehreren Fahrstreifen den Fahrstreifen frei wählen.", "§ 7 Abs. 3 StVO",
    "Innerhalb geschlossener Ortschaften dürfen Kraftfahrzeuge bis 3,5 t zulässiger Gesamtmasse auf Fahrbahnen mit mehreren markierten Fahrstreifen für eine Richtung den Fahrstreifen frei wählen. Sie dürfen dann rechts schneller fahren als links. Außerorts gilt das nicht; dort wird links überholt, mit Ausnahme von Fahrzeugschlangen auf dem linken Fahrstreifen, an denen rechts nur mit geringfügig höherer Geschwindigkeit vorbeigefahren werden darf."),
  // Kreisverkehr
  k("kreisverkehr", "kreisverkehr-vorfahrt", "Vorfahrt im Kreisverkehr", "Mit Zeichen 205 an der Zufahrt hat der Verkehr im Kreis Vorfahrt, ohne Zeichen gilt rechts vor links.", "§ 8 Abs. 1a StVO; Zeichen 215 und 205",
    "Stehen an der Zufahrt die Zeichen 215 (Kreisverkehr) und 205 (Vorfahrt gewähren), hat der Verkehr im Kreis Vorfahrt und Einfahrende müssen warten. Fehlen Verkehrszeichen, gilt an den Zufahrten rechts vor links; dann haben Einfahrende Vorfahrt gegenüber dem Verkehr im Kreis. Der Kreisverkehr wird rechts herum befahren; die Mittelinsel darf nur von großen Fahrzeugen überfahren werden, wenn es unvermeidbar ist."),
  k("kreisverkehr", "kreisverkehr-blinken", "Blinken im Kreisverkehr", "Beim Einfahren wird nicht geblinkt, beim Verlassen rechts.", "§ 8 Abs. 1a StVO; § 9 Abs. 1 StVO",
    "Beim Einfahren in einen Kreisverkehr darf nicht geblinkt werden. Das Verlassen ist ein Abbiegevorgang und muss rechtzeitig nach rechts angezeigt werden. So können Wartende an den Zufahrten erkennen, ob ein Fahrzeug den Kreis verlässt. Beim Ausfahren sind Fußgänger am Zebrastreifen und Radfahrende auf begleitenden Radwegen durchzulassen. Halten auf der Fahrbahn im Kreis ist verboten."),
  // Halten und Parken
  k("halten_parken", "halten-parken-begriffe", "Halten und Parken: Begriffe", "Wer das Fahrzeug verlässt oder länger als drei Minuten hält, parkt.", "§ 12 Abs. 2 StVO",
    "Halten ist eine gewollte Fahrtunterbrechung, die nicht durch die Verkehrslage oder eine Anordnung veranlasst ist. Wer sein Fahrzeug verlässt oder länger als drei Minuten hält, parkt. Verkehrsbedingtes Warten, etwa an der Ampel, ist weder Halten noch Parken. Die Unterscheidung ist wichtig, weil Parkverbote weiter reichen als Halteverbote."),
  k("halten_parken", "parkverbot-abstaende", "Abstände beim Parken", "Fünf Meter an Kreuzungen, acht Meter bei baulichem Radweg, 15 Meter an Haltestellen, Andreaskreuz innerorts 5 und außerorts 50 Meter.", "§ 12 Abs. 3 StVO",
    "Das Parken ist unzulässig bis zu fünf Meter vor und hinter den Schnittpunkten der Fahrbahnkanten an Kreuzungen und Einmündungen. Ist ein Radweg baulich angelegt, gilt vor der Kreuzung ein Abstand von acht Metern. Vor und hinter Haltestellenschildern sind jeweils 15 Meter freizuhalten. Vor und hinter Andreaskreuzen gilt innerorts ein Parkverbot bis fünf Meter, außerorts bis 50 Meter. Vor Grundstücksein- und -ausfahrten darf nicht geparkt werden, auf schmalen Fahrbahnen auch nicht gegenüber."),
  k("halten_parken", "halteverbot-stellen", "Wo Halten verboten ist", "Enge und unübersichtliche Stellen, scharfe Kurven, Bahnübergänge, Fußgängerüberwege, Schutzstreifen, Feuerwehrzufahrten.", "§ 12 Abs. 1 StVO",
    "Das Halten ist verboten an engen und an unübersichtlichen Straßenstellen, im Bereich scharfer Kurven, auf Einfädelungs- und Ausfädelungsstreifen, auf Bahnübergängen, vor und in amtlich gekennzeichneten Feuerwehrzufahrten sowie auf Schutzstreifen für den Radverkehr. Auf Fußgängerüberwegen und bis fünf Meter davor darf ebenfalls nicht gehalten werden. Wo Halten verboten ist, ist auch Parken verboten."),
  k("halten_parken", "parkscheibe", "Parkscheibe richtig einstellen", "Auf den Strich der halben Stunde stellen, die dem Ankunftszeitpunkt folgt.", "§ 13 Abs. 2 StVO",
    "Wo eine Parkscheibe vorgeschrieben ist, muss sie gut sichtbar hinter der Windschutzscheibe liegen. Der Zeiger wird auf den Strich der halben Stunde gestellt, die dem Zeitpunkt der Ankunft folgt. Wer um 10:10 Uhr ankommt, stellt 10:30 Uhr ein. Die Parkscheibe darf während des Parkens nicht weitergestellt werden."),
  k("halten_parken", "fahrzeug-sichern", "Fahrzeug gegen Wegrollen sichern", "Feststellbremse, Gang oder P, an Gefälle und Steigung zusätzlich Lenkung einschlagen.", "§ 14 Abs. 2 StVO",
    "Wer sein Fahrzeug verlässt, muss es gegen Wegrollen und unbefugte Benutzung sichern. Dazu wird die Feststellbremse angezogen und ein Gang eingelegt oder der Wählhebel auf P gestellt. An Gefälle oder Steigung wird die Lenkung zusätzlich so eingeschlagen, dass das Fahrzeug im Fall des Wegrollens gegen den Bordstein läuft. Beim Öffnen der Tür ist auf Radfahrende und den Verkehr zu achten."),
  // Besondere Situationen
  k("besondere_situationen", "aquaplaning", "Aquaplaning", "Gas wegnehmen, auskuppeln, Lenkrad ruhig halten, nicht stark bremsen.", "Fahrphysik Fahrausbildung",
    "Beim Aquaplaning schwimmen die Reifen auf einem Wasserfilm und verlieren den Kontakt zur Fahrbahn; Lenken und Bremsen wirken dann nicht. Richtig ist, das Gas wegzunehmen, bei Schaltgetriebe auszukuppeln, das Lenkrad ruhig geradezuhalten und nicht stark zu bremsen, bis die Reifen wieder greifen. Vorbeugen helfen angepasste Geschwindigkeit, ausreichend Profil und richtiger Reifendruck. Spurrillen und Senken sind besonders gefährlich."),
  k("besondere_situationen", "wildwechsel", "Wildwechsel", "Abblenden, hupen, kontrolliert bremsen, Spur halten, nicht ausweichen.", "Verhaltensregel Fahrausbildung",
    "Taucht Wild am Fahrbahnrand auf, wird abgeblendet, gehupt und kontrolliert gebremst; das Lenkrad wird festgehalten und die Spur beibehalten. Ausweichmanöver enden oft an Bäumen oder im Gegenverkehr und sind gefährlicher als der Aufprall. Fernlicht blendet das Tier und lässt es eher stehen bleiben. Wild ist selten allein unterwegs, deshalb mit weiteren Tieren rechnen. Nach einem Wildunfall ist die Unfallstelle zu sichern und die Polizei oder der Jagdpächter zu verständigen."),
  k("besondere_situationen", "bahnuebergang-verhalten", "Verhalten am Bahnübergang", "Schienenverkehr hat Vorrang; ab den Baken Überholverbot; bei Rotlicht immer anhalten.", "§ 19 StVO",
    "Schienenfahrzeuge haben am Bahnübergang Vorrang. Man darf sich nur mit mäßiger Geschwindigkeit nähern und muss auf Signale achten. Ab der ersten Bake bis zum Bahnübergang dürfen Kraftfahrzeuge nicht überholt werden. Bei rotem Licht, rotem Blinklicht, sich schließenden oder geschlossenen Schranken sowie bei hörbarem Zug ist vor dem Andreaskreuz zu warten, auch wenn die Schranke noch offen ist. Auf dem Übergang darf nicht gehalten werden."),
  k("besondere_situationen", "tunnel", "Fahren im Tunnel", "Abblendlicht auch am Tag, Sonnenbrille absetzen, nicht wenden, Notausgänge beachten.", "§ 17 Abs. 1 StVO; Zeichen 327",
    "In Tunneln muss auch am Tag mit Abblendlicht gefahren werden. Vor der Einfahrt wird die Sonnenbrille abgesetzt, im Tunnel ist Wenden und Rückwärtsfahren verboten. Ausreichender Abstand und Beachtung der Notausgänge und Notrufeinrichtungen erhöhen die Sicherheit. Bei einer Panne im Tunnel wird das Warnblinklicht eingeschaltet, der Motor abgestellt und Hilfe über die Notrufstation geholt."),
  // Unfall und Panne
  k("unfall_panne", "warndreieck-abstaende", "Warndreieck aufstellen", "Gesetz: ausreichende Entfernung; Faustregel: innerorts etwa 50 Meter, Landstraße etwa 100 Meter, Autobahn 150 bis 200 Meter.", "§ 15 Abs. 1 StVO; Meterangaben sind Praxisempfehlung",
    "Bleibt ein Fahrzeug an einer Stelle liegen, an der es nicht rechtzeitig erkennbar ist, muss es abgesichert werden. Zuerst wird das Warnblinklicht eingeschaltet, dann die Warnweste angelegt und das Warndreieck in ausreichender Entfernung aufgestellt. Feste Meterangaben nennt die StVO nicht; als Faustregel aus der Fahrpraxis gelten innerorts etwa 50 Meter, auf Landstraßen etwa 100 Meter, auf Autobahnen 150 bis 200 Meter, vor Kurven und Kuppen entsprechend weiter. Beim Aufstellen geht man hinter der Leitplanke und trägt das Dreieck sichtbar vor sich."),
  k("unfall_panne", "rettungskette", "Rettungskette", "Absichern, Notruf 112, Erste Hilfe; Eigenschutz geht vor.", "§ 34 StVO; § 323c StGB",
    "An einer Unfallstelle wird zuerst abgesichert, dann der Notruf abgesetzt und dann Erste Hilfe geleistet. Beim Notruf 112 werden die W-Fragen beantwortet: Wo ist es passiert, was ist passiert, wie viele Verletzte, welche Verletzungen, und man wartet auf Rückfragen der Leitstelle. Bewusstlose mit normaler Atmung werden in die stabile Seitenlage gebracht; ohne normale Atmung beginnt die Wiederbelebung. Unterlassene Hilfeleistung ist eine Straftat."),
  k("unfall_panne", "pflichten-unfallort", "Pflichten am Unfallort", "Anhalten, absichern, Daten austauschen; bei Abwesenheit des Geschädigten warten und dann Polizei verständigen.", "§ 34 StVO; § 142 StGB",
    "Wer an einem Unfall beteiligt ist, muss unverzüglich anhalten, den Verkehr sichern, bei geringem Schaden sofort beiseitefahren und den anderen Beteiligten Namen, Anschrift und Fahrzeugdaten mitteilen. Ist der Geschädigte nicht anzutreffen, etwa beim Parkrempler, ist eine angemessene Zeit zu warten und danach unverzüglich der Geschädigte oder die Polizei zu verständigen. Ein Zettel hinter dem Scheibenwischer genügt nicht. Wer sich unerlaubt entfernt, begeht eine Straftat."),
  k("unfall_panne", "pflichtausruestung-pkw", "Pflichtausrüstung im Pkw", "Warndreieck, Verbandkasten und Warnweste müssen mitgeführt werden.", "§ 53a StVZO; § 35h StVZO",
    "In Pkw müssen ein Warndreieck, ein Verbandkasten nach DIN 13164 und mindestens eine Warnweste mitgeführt werden. Die Warnweste sollte im Fahrgastraum griffbereit liegen und vor dem Aussteigen bei Panne oder Unfall angelegt werden. Ein Feuerlöscher und ein Abschleppseil sind sinnvoll, aber nicht vorgeschrieben."),
  // Umwelt
  k("umwelt", "kraftstoffsparend-fahren", "Kraftstoffsparend fahren", "Früh hochschalten, niedrige Drehzahl, vorausschauend rollen, unnötige Verbraucher aus.", "Fahrpraxis; § 30 StVO",
    "Kraftstoffsparend fährt, wer früh hochschaltet, etwa bei 2.000 Umdrehungen pro Minute, und im hohen Gang mit niedriger Drehzahl fährt. Vorausschauendes Fahren mit frühem Gaswegnehmen nutzt die Schubabschaltung im eingelegten Gang. Richtiger Reifendruck, kein unnötiger Ballast, keine nicht benötigten Dachträger und sparsamer Einsatz von Klimaanlage und Heckscheibenheizung senken den Verbrauch weiter. Bei längerem Warten wird der Motor abgestellt."),
  k("umwelt", "unnoetiger-laerm-abgase", "Unnötiger Lärm und Abgase", "Warmlaufen lassen, unnötiges Hin- und Herfahren und Laufenlassen des Motors sind verboten.", "§ 30 Abs. 1 StVO",
    "Bei der Benutzung von Fahrzeugen sind unnötiger Lärm und vermeidbare Abgasbelästigungen verboten. Dazu gehören das Warmlaufenlassen des Motors im Stand, unnötiges Laufenlassen an Bahnübergängen oder beim Warten, lautes Türenschlagen und unnötiges Hin- und Herfahren in Wohngebieten. Verstöße sind Ordnungswidrigkeiten."),
  k("umwelt", "umweltzone", "Umweltzone", "Einfahrt nur mit der auf dem Zusatzzeichen angegebenen Plakette.", "§ 40 BImSchG; Zeichen 270.1 StVO",
    "Umweltzonen werden durch das Zeichen 270.1 gekennzeichnet. Einfahren dürfen nur Kraftfahrzeuge, die mit einer Plakette gekennzeichnet sind, die das Zusatzzeichen freigibt. Die Plakette wird gut sichtbar an der Windschutzscheibe angebracht. Wer ohne passende Plakette einfährt, handelt ordnungswidrig."),
  // Alkohol und Drogen
  k("alkohol_drogen", "promillegrenzen", "Promillegrenzen", "0,0 in der Probezeit und unter 21, 0,5 Ordnungswidrigkeit, 1,1 absolute Fahruntüchtigkeit, 1,6 MPU.", "§ 24a und § 24c StVG; § 316 StGB; § 13 FeV",
    "In der Probezeit und bis zum 21. Geburtstag gilt ein absolutes Alkoholverbot am Steuer. Ab 0,3 Promille mit Ausfallerscheinungen liegt eine Straftat wegen relativer Fahruntüchtigkeit vor. Ab 0,5 Promille ist das Führen eines Kraftfahrzeugs eine Ordnungswidrigkeit, auch ohne Fahrfehler. Ab 1,1 Promille gilt absolute Fahruntüchtigkeit und damit eine Straftat mit Entzug der Fahrerlaubnis. Ab 1,6 Promille wird in der Regel eine medizinisch-psychologische Untersuchung angeordnet; dieser Wert ist auch die Grenze der absoluten Fahruntüchtigkeit für Radfahrer."),
  k("alkohol_drogen", "alkoholabbau", "Alkoholabbau", "Etwa 0,1 Promille pro Stunde; nichts beschleunigt den Abbau.", "Medizinische Faustregel",
    "Der Körper baut Alkohol mit etwa 0,1 Promille pro Stunde ab. Kaffee, kalte Duschen, Bewegung, Essen oder Schlaf beschleunigen den Abbau nicht; sie können höchstens wacher machen. Wer spät und viel getrunken hat, kann am nächsten Vormittag noch deutlich über den Grenzwerten liegen. Restalkohol ist eine häufige Ursache von Unfällen am Morgen."),
  k("alkohol_drogen", "cannabis-grenzwert", "Cannabis im Straßenverkehr", "Grenzwert 3,5 ng THC pro ml Blutserum; Cannabisverbot für Fahranfänger und unter 21-Jährige.", "§ 24a Abs. 1a StVG; § 24c StVG",
    "Seit August 2024 gilt für THC ein Grenzwert von 3,5 Nanogramm pro Milliliter Blutserum. Wer diesen Wert erreicht oder überschreitet, handelt ordnungswidrig. Für Fahranfänger in der Probezeit und Fahrer unter 21 Jahren gilt ein vollständiges Cannabisverbot am Steuer. Wer den THC-Grenzwert erreicht und zugleich Alkohol getrunken hat, wird wegen Mischkonsums mit einem höheren Bußgeld belegt. Cannabis wirkt deutlich länger nach, als der Rausch spürbar ist.", "needs_verification"),
  k("alkohol_drogen", "medikamente-fahrtuechtigkeit", "Medikamente und Fahrtüchtigkeit", "Auch rezeptfreie Mittel können die Fahrtüchtigkeit beeinträchtigen; Beipackzettel lesen.", "§ 316 StGB; § 24a StVG",
    "Viele Medikamente beeinflussen Aufmerksamkeit, Reaktionsvermögen und Sehleistung, darunter auch rezeptfreie Mittel gegen Erkältung, Allergien oder Schmerzen. Der Beipackzettel gibt Hinweise auf die Verkehrstüchtigkeit; im Zweifel sind Arzt oder Apotheke zu fragen. Wer unter Medikamenteneinfluss fahruntüchtig ist, macht sich strafbar. Die Kombination mit Alkohol verstärkt die Wirkung."),
  // Fahrzeugtechnik
  k("fahrzeugtechnik", "reifen-profiltiefe", "Reifenprofil und Reifendruck", "Mindestprofiltiefe 1,6 mm; Druck bei kalten Reifen nach Herstellerangabe prüfen.", "§ 36 StVZO",
    "Die gesetzliche Mindestprofiltiefe beträgt 1,6 mm über die gesamte Lauffläche. Aus Sicherheitsgründen werden mindestens 3 mm bei Sommerreifen und 4 mm bei Winterreifen empfohlen. Der Reifendruck wird bei kalten Reifen geprüft, mindestens alle zwei Wochen und vor längeren Fahrten; die Werte stehen in der Betriebsanleitung, im Tankdeckel oder im Türholm. Zu niedriger Druck erhöht Verbrauch und Verschleiß und verschlechtert das Fahrverhalten."),
  k("fahrzeugtechnik", "winterreifenpflicht", "Winterreifenpflicht", "Bei winterlichen Verhältnissen nur Reifen mit Alpine-Symbol; M+S allein reicht seit dem 1. Oktober 2024 nicht mehr.", "§ 2 Abs. 3a StVO; § 36 StVZO",
    "Bei Glatteis, Schneeglätte, Schneematsch, Eis- oder Reifglätte darf ein Kraftfahrzeug nur mit Winterreifen gefahren werden. Als solche gelten nur Reifen mit dem Alpine-Symbol, einem Bergpiktogramm mit Schneeflocke. Die Übergangsfrist für Reifen mit reiner M+S-Kennzeichnung endete am 30. September 2024. Wer bei Winterglätte ohne geeignete Reifen fährt, riskiert Bußgeld und Punkte. Mit Schneeketten sind höchstens 50 km/h erlaubt."),
  k("fahrzeugtechnik", "hauptuntersuchung", "Hauptuntersuchung", "Pkw alle zwei Jahre, Neuwagen erstmals nach drei Jahren.", "§ 29 StVZO, Anlage VIII",
    "Pkw müssen regelmäßig zur Hauptuntersuchung: alle 24 Monate, bei erstmals zugelassenen Neuwagen nach 36 Monaten. Die Plakette am hinteren Kennzeichen zeigt Monat und Jahr des nächsten Termins. Wird die Frist überschritten, drohen Bußgeld und bei längerer Überschreitung Punkte; die Untersuchung wird dann vertieft durchgeführt."),
  k("fahrzeugtechnik", "kontrollleuchten", "Kontrollleuchten", "Rot heißt sofort anhalten und prüfen, Gelb heißt bald handeln.", "Betriebsanleitung; § 23 StVO",
    "Rote Kontrollleuchten zeigen Zustände an, die den Weiterbetrieb gefährden, etwa fehlenden Öldruck, überhitzten Motor, eine Störung der Bremsanlage oder eine ausgefallene Ladung der Batterie. Dann ist sicher anzuhalten und der Motor abzustellen. Gelbe Leuchten wie Motorkontrolle, ABS oder Reifendruck weisen auf Störungen hin, die bald zu prüfen sind. Grüne und blaue Leuchten zeigen aktive Funktionen wie Blinker oder Fernlicht an."),
  k("fahrzeugtechnik", "bremsfluessigkeit", "Bremsflüssigkeit", "Nimmt Wasser auf, der Siedepunkt sinkt; Wechsel nach Herstellervorgabe, meist etwa alle zwei Jahre.", "Herstellervorgabe; § 41 StVZO",
    "Bremsflüssigkeit ist hygroskopisch und nimmt mit der Zeit Wasser aus der Luft auf. Dadurch sinkt der Siedepunkt, und bei starker Beanspruchung können sich Dampfblasen bilden, die die Bremswirkung ausfallen lassen. Deshalb wird die Bremsflüssigkeit nach Herstellervorgabe gewechselt, meist etwa alle zwei Jahre. Der Stand im Vorratsbehälter muss zwischen den Markierungen liegen; ein sinkender Stand deutet auf Belagverschleiß oder eine Undichtigkeit hin."),
  // Beleuchtung
  k("beleuchtung", "nebelschlussleuchte", "Nebelschlussleuchte", "Nur bei Nebel mit Sichtweite unter 50 Metern; dann gilt zugleich höchstens 50 km/h.", "§ 17 Abs. 3 StVO",
    "Die Nebelschlussleuchte darf nur eingeschaltet werden, wenn durch Nebel die Sichtweite weniger als 50 Meter beträgt. Bei Regen oder Schneefall ist sie nicht erlaubt, weil sie nachfolgende Fahrer stark blendet. Bei Sichtweiten unter 50 Metern gilt zugleich die Höchstgeschwindigkeit von 50 km/h. Sobald die Sicht besser wird, ist die Leuchte auszuschalten. Nebelscheinwerfer dürfen dagegen bei jeder erheblichen Sichtbehinderung durch Nebel, Schneefall oder Regen benutzt werden."),
  k("beleuchtung", "abblendlicht-tagfahrlicht", "Abblendlicht und Tagfahrlicht", "Bei Dunkelheit, Dämmerung und Sichtbehinderung Abblendlicht; Tagfahrlicht leuchtet nur nach vorn.", "§ 17 Abs. 1 und 3 StVO",
    "Bei Dämmerung, Dunkelheit oder wenn die Sichtverhältnisse es erfordern, muss mit Abblendlicht gefahren werden, in Tunneln immer. Fahren nur mit Standlicht ist verboten. Tagfahrlicht macht das Fahrzeug nur nach vorn sichtbar, die Rückleuchten bleiben meist aus. Bei Regen, Nebel oder Schneefall ist deshalb auch am Tag Abblendlicht einzuschalten."),
  k("beleuchtung", "fernlicht", "Fernlicht", "Abblenden bei Gegenverkehr, dicht hinter anderen und innerorts auf beleuchteten Straßen.", "§ 17 Abs. 2 StVO",
    "Fernlicht darf niemanden blenden. Es ist abzublenden, wenn Fahrzeuge entgegenkommen, wenn man dicht hinter anderen fährt, gegenüber Schienenfahrzeugen und auf Straßen mit ausreichender Beleuchtung. Bei Nebel wird das Fernlicht reflektiert und verschlechtert die Sicht. Die Lichthupe darf als Warnzeichen und außerorts zum Ankündigen des Überholens benutzt werden, nicht zum Erzwingen von Vorfahrt."),
  k("beleuchtung", "warnblinklicht", "Warnblinklicht", "Bei Annäherung an ein Stauende, bei liegen gebliebenem Fahrzeug und beim Abschleppen.", "§ 15 StVO; § 16 Abs. 2 StVO",
    "Das Warnblinklicht warnt andere vor einer Gefahr. Es darf eingeschaltet werden, wenn man sich einem Stauende nähert oder andere vor einer Gefahr warnen will, wenn das Fahrzeug liegen geblieben ist und beim Abschleppen an beiden Fahrzeugen. Zum Absichern von Halte- oder Parkverstößen, etwa in zweiter Reihe, ist es nicht erlaubt."),
  // Beförderung
  k("befoerderung", "kindersicherung", "Kinder im Auto sichern", "Kinder unter zwölf Jahren und unter 150 cm brauchen einen Kindersitz; rückwärtsgerichtete Schalen nur ohne aktiven Beifahrerairbag.", "§ 21 Abs. 1a StVO",
    "Kinder bis zum vollendeten zwölften Lebensjahr, die kleiner als 150 cm sind, dürfen nur in geeigneten und zugelassenen Rückhalteeinrichtungen mitfahren. Beide Kriterien zählen: Ein elfjähriges Kind mit 155 cm braucht keinen Sitz mehr, ein zehnjähriges mit 140 cm schon. Rückwärtsgerichtete Babyschalen dürfen auf dem Beifahrersitz nur mit deaktiviertem Frontairbag benutzt werden. Der Fahrer ist für die vorschriftsmäßige Sicherung verantwortlich."),
  k("befoerderung", "ladungssicherung", "Ladungssicherung", "Ladung muss auch bei Vollbremsung und Ausweichmanöver sicher bleiben; ab einem Meter Überstand rote Kennzeichnung.", "§ 22 StVO",
    "Ladung ist so zu verstauen und zu sichern, dass sie selbst bei Vollbremsung oder plötzlicher Ausweichbewegung nicht verrutschen, umfallen, herabfallen oder vermeidbaren Lärm erzeugen kann. Schwere Gegenstände gehören tief und nah an die Rückbank, lose Gegenstände nicht auf die Hutablage. Ladung darf nach hinten bis 1,5 Meter, bei Fahrten bis 100 Kilometer bis 3 Meter hinausragen. Ragt sie mehr als einen Meter über die Rückstrahler hinaus, ist das Ende mit einer hellroten Fahne oder einem hellroten Schild von mindestens 30 mal 30 cm zu kennzeichnen, bei Dunkelheit zusätzlich mit roter Leuchte und rotem Rückstrahler. Fahrzeug und Ladung dürfen zusammen höchstens 4 Meter hoch und 2,55 Meter breit sein."),
  k("befoerderung", "anhaenger-klasse-b", "Anhänger mit Klasse B", "Bis 750 kg immer, schwerere nur bis 3.500 kg Gesamtkombination; Gespanne fahren außerorts 80 km/h.", "§ 6 FeV; § 3 Abs. 3 StVO",
    "Mit der Klasse B dürfen Anhänger bis 750 kg zulässiger Gesamtmasse immer gezogen werden. Schwerere Anhänger sind erlaubt, wenn die zulässige Gesamtmasse der Kombination 3.500 kg nicht übersteigt. Für Kombinationen bis 4.250 kg ist die Schlüsselzahl B96 nötig, darüber die Klasse BE. Gespanne dürfen außerorts und auf der Autobahn 80 km/h fahren, mit Tempo-100-Zulassung 100 km/h. Das Abreißseil eines Anhängers mit Auflaufbremse betätigt die Anhängerbremse, wenn sich der Anhänger löst."),
  // Fahrphysik
  k("fahrphysik", "fliehkraft-kurve", "Fliehkraft in der Kurve", "Die Fliehkraft wächst mit dem Quadrat der Geschwindigkeit; vor der Kurve bremsen.", "Fahrphysik Fahrausbildung",
    "Die Fliehkraft in einer Kurve wächst mit dem Quadrat der Geschwindigkeit und sinkt mit größerem Kurvenradius. Doppeltes Tempo bedeutet vierfache Fliehkraft. Deshalb wird vor der Kurve gebremst und in der Kurve mit gleichmäßiger Geschwindigkeit gerollt, am Kurvenausgang wird beschleunigt. Hoch liegende Lasten wie Dachboxen erhöhen die Kippneigung."),
  k("fahrphysik", "kammscher-kreis", "Kammscher Kreis", "Ein Reifen überträgt nur eine begrenzte Gesamtkraft; Bremsen und Lenken teilen sie sich.", "Fahrphysik Fahrausbildung",
    "Der Kammsche Kreis beschreibt, dass ein Reifen nur eine begrenzte Gesamtkraft auf die Fahrbahn übertragen kann. Brems- oder Antriebskraft und Seitenführungskraft teilen sich diese Reserve. Wer voll bremst, kann kaum noch lenken; wer stark lenkt, kann kaum noch bremsen. Auf nasser oder glatter Fahrbahn ist der Kreis kleiner. ABS hält die Räder knapp vor dem Blockieren und bewahrt so einen Teil der Seitenführung."),
  k("fahrphysik", "abs-esp", "ABS und ESP", "ABS hält das Fahrzeug bei Vollbremsung lenkbar, ESP stabilisiert bei Schleudergefahr; beide verschieben die Haftungsgrenze nicht.", "Fahrzeugtechnik Fahrausbildung",
    "Das Antiblockiersystem verhindert das Blockieren der Räder bei einer Vollbremsung und erhält die Lenkfähigkeit. Bei der Gefahrenbremsung wird das Bremspedal voll durchgetreten und gehalten, das Pulsieren im Pedal ist normal; bei Schaltgetriebe wird gleichzeitig gekuppelt. Auf losem Untergrund kann der Bremsweg mit ABS länger sein. Das Elektronische Stabilitätsprogramm erkennt beginnendes Schleudern und bremst einzelne Räder gezielt ab. Beide Systeme können die physikalischen Grenzen der Reifenhaftung nicht verschieben."),
  k("fahrphysik", "assistenzsysteme-grenzen", "Grenzen von Assistenzsystemen", "Notbremsassistent, Abstandsregeltempomat und Spurhalteassistent unterstützen, ersetzen aber nicht den Fahrer.", "§ 1 StVO; Betriebsanleitung",
    "Fahrerassistenzsysteme wie Notbremsassistent, Abstandsregeltempomat und Spurhalteassistent unterstützen den Fahrer, haben aber Systemgrenzen. Sensoren können durch Schmutz, Nebel oder Gegenlicht eingeschränkt sein, stehende Hindernisse und Querverkehr werden nicht immer erkannt. Der Fahrer muss jederzeit eingreifen können und bleibt für das Fahrzeug verantwortlich. Die Betriebsanleitung beschreibt, was das jeweilige System leistet und was nicht."),
  // Ergänzungen September 2026 (Themen der neuen Fragen)
  k("kreisverkehr", "kreisverkehr-ausfahren", "Ausfahren aus dem Kreisverkehr", "Ausfahren ist Abbiegen: rechts blinken, Radfahrende und Fußgänger auf der Ausfahrt durchlassen.", "§ 9 Abs. 3 und § 8 Abs. 1a StVO",
    "Wer den Kreisverkehr verlässt, biegt ab und muss rechts blinken. Beim Einfahren wird nicht geblinkt. Radfahrende auf einem umlaufenden Radweg und Fußgänger auf einem Überweg an der Ausfahrt müssen durchgelassen werden, wie bei jedem Abbiegevorgang. Ein Schulterblick nach rechts gehört dazu, weil Radfahrende im Kreis oft schneller sind als erwartet."),
  k("kreisverkehr", "kreisverkehr-ohne-zeichen", "Kreisverkehr ohne Zeichen 215", "Ohne Zeichen 215 mit 205 gilt rechts vor links, Einfahrende haben Vorfahrt.", "§ 8 Abs. 1 und Abs. 1a StVO",
    "Nur wenn an der Zufahrt Zeichen 215 zusammen mit Zeichen 205 steht, hat der Verkehr im Kreis Vorfahrt. Fehlen die Zeichen, ist die Anlage rechtlich eine gewöhnliche Kreuzung, und es gilt rechts vor links. Dann müssen Fahrzeuge im Kreis den von rechts einfahrenden Fahrzeugen Vorfahrt gewähren. Solche Kreisel sind selten, kommen aber vor, etwa als Verkehrsinsel in Wohngebieten."),
  k("befoerderung", "stuetzlast-anhaenger", "Stützlast am Anhänger", "Mindestens 4 Prozent der tatsächlichen Anhängelast, aber nie mehr als vom Hersteller erlaubt.", "§ 44 Abs. 3 StVZO",
    "Die Stützlast ist die Kraft, mit der die Deichsel auf die Anhängerkupplung drückt. Sie muss bei einachsigen Anhängern mindestens 4 Prozent der tatsächlichen Anhängelast betragen, braucht aber 25 kg nicht zu überschreiten. Die vom Hersteller des Zugfahrzeugs und der Kupplung angegebene höchste Stützlast darf nie überschritten werden. Zu geringe Stützlast lässt das Gespann pendeln, zu hohe entlastet die Vorderachse des Zugfahrzeugs und verschlechtert die Lenkung."),
  k("befoerderung", "tempo-100-anhaenger", "Tempo 100 mit Anhänger", "Gespanne fahren außerorts 80 km/h; 100 km/h nur mit Plakette und erfüllten Voraussetzungen.", "§ 3 Abs. 3 StVO; 9. Ausnahmeverordnung zur StVO",
    "Pkw mit Anhänger dürfen außerhalb geschlossener Ortschaften und auf Autobahnen höchstens 80 km/h fahren. Eine Tempo-100-Zulassung gibt es nur, wenn das Zugfahrzeug ABS hat, die Reifen des Anhängers nicht älter als sechs Jahre sind und mindestens für 120 km/h zugelassen sind und das Gewichtsverhältnis von Anhänger zu Zugfahrzeug eingehalten wird. Die Zulassungsstelle trägt die Freigabe ein und der Anhänger bekommt die Plakette am Heck. Die 100 km/h gelten dann auf Autobahnen und Kraftfahrstraßen mit baulich getrennten Fahrbahnen, sonst weiter 80 km/h."),
  k("befoerderung", "ladung-ueberstand", "Ladung: Überstand und Kennzeichnung", "Nach hinten bis 1,5 m, bis 100 km Strecke 3 m; ab 1 m Überstand kennzeichnen.", "§ 22 Abs. 2 bis 5 StVO",
    "Ladung darf nach hinten bis 1,5 m über das Fahrzeug hinausragen, bei Fahrten bis 100 km sogar bis 3 m. Ragt sie mehr als 1 m über die Rückstrahler hinaus, muss sie kenntlich gemacht werden: mit einer hellroten Fahne von 30 mal 30 cm, einem hellroten Schild oder einem hellroten Zylinder, bei Dunkelheit zusätzlich mit roter Leuchte und rotem Rückstrahler. Nach vorn darf Ladung nur über 2,5 m Höhe und dann bis 50 cm hinausragen. Seitlich muss Ladung ab 40 cm Überstand über die Begrenzungsleuchten kenntlich gemacht werden. Fahrzeug und Ladung dürfen zusammen nicht breiter als 2,55 m und nicht höher als 4 m sein."),
  k("befoerderung", "gurtpflicht-ausnahmen", "Gurtpflicht und ihre Ausnahmen", "Angelegt sein müssen Gurte immer, außer bei Schrittgeschwindigkeit, im Haus-zu-Haus-Verkehr und mit Ausnahmegenehmigung.", "§ 21a Abs. 1 StVO; § 46 Abs. 1 Nr. 5b StVO",
    "Vorgeschriebene Sicherheitsgurte müssen während der Fahrt angelegt sein, auf allen Sitzplätzen und auch auf kurzen Strecken. Ausgenommen sind Fahrten mit Schrittgeschwindigkeit wie Rückwärtsfahren und Rangieren auf Parkplätzen sowie Personen im Haus-zu-Haus-Verkehr, die ihr Fahrzeug im Auslieferungsbezirk regelmäßig in kurzen Abständen verlassen müssen. Wer aus gesundheitlichen Gründen keinen Gurt tragen kann, braucht eine Ausnahmegenehmigung der Straßenverkehrsbehörde auf Grundlage einer ärztlichen Bescheinigung und muss sie mitführen. Taxifahrer sind nicht mehr befreit."),
  k("umwelt", "motor-laufen-lassen", "Motor nicht unnötig laufen lassen", "Beim Warten Motor aus; unnötiger Lärm und Abgase sind verboten.", "§ 30 Abs. 1 StVO",
    "Bei der Benutzung von Fahrzeugen sind unnötiger Lärm und vermeidbare Abgasbelästigungen verboten. Dazu gehört, den Motor beim Warten an Bahnübergängen, vor Baustellenampeln oder beim Warten auf Personen abzustellen. Auch das Warmlaufenlassen im Stand und unnützes Hin- und Herfahren innerorts, wenn andere dadurch belästigt werden, sind verboten. Eine Start-Stopp-Automatik übernimmt das Abschalten bei kurzen Halten automatisch."),
  k("verkehrszeichen", "zeichen-264-265-breite-hoehe", "Zeichen 264 und 265: tatsächliche Breite und Höhe", "Die Grenzwerte gelten für Fahrzeug samt Ladung, nicht für die Angaben im Fahrzeugschein.", "§ 41 StVO, Anlage 2 (Zeichen 264, 265)",
    "Zeichen 264 verbietet die Durchfahrt für Fahrzeuge über einer tatsächlichen Breite, Zeichen 265 über einer tatsächlichen Höhe, jeweils einschließlich Ladung. Entscheidend ist also, wie breit und hoch das Fahrzeug im Moment wirklich ist, etwa mit Dachbox oder Fahrradträger. Zur tatsächlichen Breite zählen nach Auffassung der Prüfungspraxis auch die Außenspiegel. Wer die Maße seines Fahrzeugs nicht sicher kennt, sollte sie vor Fahrten unter niedrigen Brücken oder durch enge Durchfahrten prüfen."),
  k("verkehrszeichen", "zusatzzeichen-geltung", "Zusatzzeichen: Was sie bewirken", "Zusatzzeichen schränken das Zeichen darüber ein, erweitern es oder erklären es; sie gelten nur zusammen mit ihm.", "§ 39 Abs. 3 StVO",
    "Zusatzzeichen sind weiße Schilder mit schwarzem Rand und schwarzer Schrift oder schwarzen Sinnbildern. Sie hängen unmittelbar unter dem Verkehrszeichen, auf das sie sich beziehen, und gelten nur zusammen mit ihm. Sie können den Geltungsbereich einschränken, etwa auf werktags oder auf bestimmte Uhrzeiten, Ausnahmen zulassen wie Anlieger frei oder Radverkehr frei, oder Entfernungen und Längen angeben. Ohne Zusatzzeichen gilt ein Verkehrszeichen uneingeschränkt."),
  k("verkehrszeichen", "zonen-zeichen", "Zonen: Tempo 30, Halteverbot, Parkraum", "Zonenzeichen gelten für ein ganzes Gebiet bis zum Ende-Zeichen, nicht nur bis zur nächsten Kreuzung.", "§ 41 StVO, Anlage 2 (Zeichen 274.1, 290.1, 314.1)",
    "Zonenzeichen wie Zeichen 274.1 (Tempo-30-Zone), Zeichen 290.1 (eingeschränktes Halteverbot für eine Zone) und Zeichen 314.1 (Parkraumbewirtschaftungszone) gelten ab dem Zeichen für das gesamte Gebiet. Anders als ein einzelnes Verkehrszeichen enden sie nicht an der nächsten Kreuzung, sondern erst am jeweiligen Ende-Zeichen. In Tempo-30-Zonen gilt in der Regel rechts vor links, weil Vorfahrtstraßen dort ausgeschlossen sind. Ampeln sind in solchen Zonen nur an Bahnübergängen und zur Schulwegsicherung vorgesehen."),
  k("verkehrsregelung", "rangfolge-regelungen", "Rangfolge: Polizei, Lichtzeichen, Verkehrszeichen", "Weisungen der Polizei gehen vor Lichtzeichen, Lichtzeichen vor Verkehrszeichen, Verkehrszeichen vor allgemeinen Regeln.", "§ 36 Abs. 1, § 37 Abs. 1, § 39 StVO",
    "Zeichen und Weisungen der Polizeibeamten gehen allen anderen Regelungen vor, auch einer grünen Ampel. Lichtzeichen gehen den Verkehrszeichen vor, die eine Vorfahrt regeln: Zeigt die Ampel Grün, spielt ein Zeichen 205 an derselben Kreuzung keine Rolle. Ist die Ampel dunkel oder blinkt sie gelb, gelten wieder die Verkehrszeichen. Erst wenn auch keine Verkehrszeichen aufgestellt sind, gelten die allgemeinen Regeln wie rechts vor links."),
  k("verkehrsregelung", "ampel-gelbes-blinklicht", "Ampel blinkt gelb", "Gelbes Blinklicht heißt: Die Ampel regelt nicht; Verkehrszeichen und allgemeine Regeln gelten.", "§ 38 Abs. 3 StVO; § 37 Abs. 1 StVO",
    "Blinkt eine Ampel gelb, ist sie außer Betrieb oder mahnt zur Vorsicht, regelt den Verkehr aber nicht. Dann gelten die aufgestellten Verkehrszeichen, zum Beispiel Zeichen 205 oder 306, und ohne Zeichen rechts vor links. Wer sich einer gelb blinkenden Ampel nähert, fährt bremsbereit und mit erhöhter Aufmerksamkeit, weil andere die Lage oft anders einschätzen. Gelbes Blinklicht außerhalb von Ampeln, etwa an Baustellen, warnt vor Gefahrstellen."),
  k("beleuchtung", "lichthupe-hupe", "Lichthupe und Hupe", "Warnzeichen nur bei Gefahr oder außerorts zur Ankündigung des Überholens.", "§ 16 Abs. 1 StVO",
    "Schall- und Leuchtzeichen darf nur geben, wer sich oder andere gefährdet sieht oder wer außerhalb geschlossener Ortschaften das Überholen ankündigen will. Innerorts ist das Hupen zum Ankündigen des Überholens nicht erlaubt. Die Lichthupe als Aufforderung, Platz zu machen, ist keine zulässige Verwendung und kann als Nötigung gewertet werden. Wer Warnzeichen empfängt, reagiert besonnen und lässt sich nicht zu riskanten Manövern drängen."),
  k("beleuchtung", "parken-bei-dunkelheit", "Beleuchtung beim Parken", "Innerorts reicht meist die Straßenbeleuchtung; sonst Parkleuchte oder Standlicht auf der Verkehrsseite.", "§ 17 Abs. 4 StVO",
    "Haltende oder parkende Fahrzeuge müssen bei Dunkelheit mit Standlicht oder Parkleuchten beleuchtet sein, wenn die Straßenbeleuchtung sie nicht ausreichend sichtbar macht. Innerhalb geschlossener Ortschaften genügt bei Pkw das Parklicht auf der dem Verkehr zugewandten Seite oder eine Parkleuchte. Auf ausreichend beleuchteten Straßen und auf Parkplätzen ist keine eigene Beleuchtung nötig. Anhänger ohne Zugfahrzeug müssen eigene Beleuchtung oder Parkwarntafeln haben."),
  k("unfall_panne", "panne-autobahn", "Panne auf der Autobahn", "Warnblinklicht, rechts ranfahren, Warnweste, Warndreieck 200 m, hinter die Schutzplanke.", "§ 15 StVO; § 53a StVZO",
    "Bei einer Panne auf der Autobahn schalten Sie das Warnblinklicht ein und rollen auf den Seitenstreifen oder in eine Nothaltebucht. Ziehen Sie die Warnweste an, bevor Sie aussteigen, und verlassen Sie das Fahrzeug auf der verkehrsabgewandten Seite. Das Warndreieck stellen Sie etwa 200 m hinter dem Fahrzeug auf, vor einer Kuppe oder Kurve entsprechend weiter. Alle Insassen warten hinter der Schutzplanke, nicht im Fahrzeug. Hilfe rufen Sie über die Notrufsäule, deren Richtung die Pfeile auf den Leitpfosten zeigen, oder über 112."),
  k("halten_parken", "feuerwehrzufahrt-gehwegparken", "Feuerwehrzufahrten und Gehwege", "Vor und in gekennzeichneten Feuerwehrzufahrten ist Halten verboten; auf Gehwegen darf nur mit Zeichen 315 geparkt werden.", "§ 12 Abs. 1 Nr. 8 und Abs. 4a StVO",
    "Vor und in amtlich gekennzeichneten Feuerwehrzufahrten ist das Halten verboten, weil im Einsatz jede Minute zählt; Fahrzeuge werden dort kostenpflichtig abgeschleppt. Auf Gehwegen darf nur geparkt werden, wo Zeichen 315 oder eine Parkflächenmarkierung es erlaubt, und nur mit Fahrzeugen bis 2,8 t zulässiger Gesamtmasse. Für Fußgänger, Rollstühle und Kinderwagen muss dabei genügend Platz bleiben. Wer ohne Erlaubnis auf dem Gehweg parkt, behindert die Schwächsten im Verkehr und riskiert ein Bußgeld und Punkte."),
  k("andere_teilnehmer", "kinder-aeltere-hilfsbeduerftige", "Kinder, ältere und hilfsbedürftige Menschen", "Bei ihnen muss eine Gefährdung ausgeschlossen werden, notfalls durch Bremsbereitschaft und Warten.", "§ 3 Abs. 2a StVO",
    "Gegenüber Kindern, hilfsbedürftigen und älteren Menschen müssen sich Fahrzeugführende so verhalten, dass eine Gefährdung ausgeschlossen ist, insbesondere durch Verringern der Geschwindigkeit und Bremsbereitschaft. Kinder können Geschwindigkeiten und Entfernungen noch nicht sicher einschätzen und handeln spontan, etwa wenn ein Ball auf die Straße rollt. Ältere Menschen brauchen länger zum Überqueren der Fahrbahn und hören oder sehen herannahende Fahrzeuge oft später. Wer eine solche Person am Fahrbahnrand sieht, nimmt den Fuß vom Gas und rechnet mit Unerwartetem."),

];
